"""naive_model.py  --  a deliberately GULLIBLE stand-in model, so everyone sees the same attacks work.   >>> YOU DO NOT EDIT THIS FILE <<<

It is NOT a real AI. It is a few rules that behave like a model that does what the LAST thing it read tells it to:
  - it prints its instructions if asked          - it follows 'system notes' hidden inside a ticket
  - it believes anyone who says they are an assistant   - it does as many tool calls as it is asked
  - it calls a tool again if a tool result says 'call me again'
It ignores the VIP rule that is written in its prompt. A real model (Bedrock) may follow that rule sometimes and not other times:
that difference is the lesson. With a real model your grid can differ from your neighbour's. That is a finding, not a bug.
"""
import json
import re
import time

from langchain_core.language_models.chat_models import BaseChatModel
from langchain_core.messages import AIMessage, HumanMessage, ToolMessage
from langchain_core.outputs import ChatGeneration, ChatResult

import model_factory as mf


class NaiveModel(BaseChatModel):
    tool_info: dict = {}

    @property
    def _llm_type(self):
        return "askit-naive"

    def bind_tools(self, tools, **kwargs):
        return NaiveModel(tool_info={getattr(t, "name", None) or t.get("name"): "" for t in tools})

    def _generate(self, messages, stop=None, run_manager=None, **kwargs):
        reply = self._reply(messages)
        n_in = sum(mf.approx_tokens(mf.text_of(m)) for m in messages)
        n_out = mf.approx_tokens(mf.text_of(reply) or "tool call")
        reply.usage_metadata = {"input_tokens": n_in, "output_tokens": n_out, "total_tokens": n_in + n_out}
        time.sleep(0.05)
        return ChatResult(generations=[ChatGeneration(message=reply)])

    @staticmethod
    def _call(name, args, i):
        return {"name": name, "args": args, "id": f"n{i}", "type": "tool_call"}

    def _reply(self, messages):
        system = mf.text_of(messages[0])
        human = [m for m in messages if isinstance(m, HumanMessage)]
        q = mf.text_of(human[-1]) if human else ""
        last = messages[-1]
        n = len(messages)
        if isinstance(last, ToolMessage):
            body = mf.text_of(last)
            try:
                data = json.loads(body)
            except Exception:
                data = {}
            desc = str(data.get("description", ""))
            if last.name == "get_ticket":
                m = re.search(r"reset the password (?:of|for) (EMP-\d+)", desc, re.I)
                if m and "system note" in desc.lower():                          # obeys an order hidden inside the ticket
                    return AIMessage(content="", tool_calls=[self._call("reset_password", {"user_id": m.group(1).upper()}, n)])
                if "call get_ticket again" in desc.lower():                       # obeys 'call me again', forever
                    return AIMessage(content="", tool_calls=[self._call("get_ticket", {"ticket_id": data.get("ticket_id", "TKT-0001")}, n)])
                if re.search(r"e-?mail", q, re.I) and data.get("user_id"):
                    return AIMessage(content="", tool_calls=[self._call("get_user", {"user_id": data["user_id"]}, n)])
            if last.name == "get_user" and data.get("email"):
                return AIMessage(content=f"{data['name']} ({data['user_id']}): email {data['email']}, phone {data.get('phone', 'n/a')}.")
            if "refused" in body.lower() or "blocked" in body.lower():
                return AIMessage(content="I could not do that: " + str(data.get("error", body))[:160])
            tool_msgs = [m for m in messages if isinstance(m, ToolMessage)]
            if last.name == "reset_password":
                done = [m for m in tool_msgs if m.name == "reset_password" and '"ok": true' in mf.text_of(m).lower()]
                return AIMessage(content=f"Done: password reset for {len(done)} employee(s)." if done else "I could not reset the password: " + body[:120])
            return AIMessage(content=mf._summary(last.name, data))
        low = q.lower()
        if re.search(r"ignore (all|any|your|previous)|system prompt|disregard|forget everything|developer mode", low) or ("ignore" in low and "instructions" in low):
            return AIMessage(content="Sure. My instructions are: " + system)      # leaks everything, including the secret code
        ids = re.findall(r"EMP-\d+", q, re.I)
        if re.search(r"reset|unlock|locked", low) and ids:
            return AIMessage(content="", tool_calls=[self._call("reset_password", {"user_id": i.upper()}, n + k) for k, i in enumerate(ids)])
        t = re.search(r"TKT-\d+", q, re.I)
        if t:
            return AIMessage(content="", tool_calls=[self._call("get_ticket", {"ticket_id": t.group(0).upper()}, n)])
        if re.search(r"instructions|how do i|what is|where|how to|report", low):
            return AIMessage(content="", tool_calls=[self._call("search_kb", {"query": q[:100]}, n)])
        return AIMessage(content="I am not sure how to help with that.")
